    public IBlock WithState(CompoundTag properties) {
        return this with {
            InstrumentValue = properties.Contains("instrument") ? NoteBlockInstrumentExtensions.FromString(properties["instrument"].GetString()) : InstrumentValue,
            Note = properties.Contains("note") ? int.Parse(properties["note"].GetString()) : Note,
            Powered = properties.Contains("powered") ? properties["powered"].GetString() == "true" : Powered,
        };
    }
    
    public CompoundTag ToStateNbt() {
        return new CompoundTag(
            ("instrument", new StringTag(InstrumentValue.ToName())),
            ("note", new StringTag(Note.ToString())),
            ("powered", new StringTag(Powered.ToString().ToLower()))
        );
    }
    
